package main

import (
	"fmt"
	"time"
	"github.com/JamalYusuf/luxon"
)

func main() {
	// Get current time
	dt := luxon.Now()

	// Add 5 days and convert to Tokyo time
	future, err := dt.PlusDays(5).InZone("Asia/Tokyo")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	// Format using Luxon-style tokens
	formatted := future.FormatLuxon("yyyy-MM-dd HH:mm")
	fmt.Println("Future in Tokyo:", formatted)

	// Snap to start of month
	startOfMonth, err := future.StartOf("month")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println("Start of month:", startOfMonth.Format("2006-01-02"))
}

package main

import (
	"fmt"
	"time"
	"github.com/JamalYusuf/luxon"
)

func main() {
	// Create a business calendar for UTC
	cal := luxon.NewBusinessCalendar(time.UTC)

	// Set weekends as non-working days
	cal.SetNonWorkingDay(time.Saturday)
	cal.SetNonWorkingDay(time.Sunday)

	// Add a holiday
	holiday := time.Date(2023, 12, 25, 0, 0, 0, 0, time.UTC)
	cal.AddHoliday(holiday)

	// Define date range
	start := luxon.Now()
	end := start.PlusDays(14)

	// Calculate business days
	businessDays := cal.BusinessDaysBetween(start, end)
	fmt.Println("Business days:", businessDays)

	// Find next business day
	next := cal.NextBusinessDay(start)
	fmt.Println("Next business day:", next.Format("2006-01-02"))
}

package main

import (
	"fmt"
	"github.com/JamalYusuf/luxon"
)

func main() {
	// Parse an iCalendar RRULE
	rule, err := luxon.ParseRRule("FREQ=WEEKLY;INTERVAL=2;BYDAY=MO,WE;COUNT=4")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	// Define time range
	start := luxon.Now()
	end := start.PlusDays(30)

	// Generate occurrences
	occurrences, err := rule.GenerateOccurrences(start, end)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	// Print occurrences
	for i, occ := range occurrences {
		fmt.Printf("Event %d: %s\n", i+1, occ.Format("2006-01-02"))
	}
}

package main

import (
	"context"
	"fmt"
	"time"
	"github.com/JamalYusuf/luxon"
)

func main() {
	ctx := context.Background()

	// Create a slice of DateTime instances
	dts := []luxon.DateTime{
		luxon.Now(),
		luxon.Now().PlusDays(1),
		luxon.Now().PlusDays(2),
	}

	// Convert to London time in parallel
	converted, err := luxon.BatchInZone(ctx, dts, "Europe/London")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	// Format results
	formatted, err := luxon.BatchFormat(ctx, converted, "2006-01-02 HH:mm")
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	// Print formatted times
	for i, f := range formatted {
		fmt.Printf("Date %d: %s\n", i+1, f)
	}
}

package main

import (
	"fmt"
	"time"
	"github.com/JamalYusuf/luxon"
)

func main() {
	// Create a mock timer set to a specific time
	mockTime := time.Date(2023, 10, 1, 12, 0, 0, 0, time.UTC)
	mock := luxon.NewMockTimer(mockTime, time.UTC)
	luxon.SetTimer(mock)

	// Check current time
	fmt.Println("Mock time:", luxon.Now().Format("2006-01-02 HH:mm"))

	// Advance time by 1 day
	err := mock.Advance(24 * time.Hour)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}

	// Check advanced time
	fmt.Println("Advanced time:", luxon.Now().Format("2006-01-02 HH:mm"))

	// Reset to default timer
	luxon.ResetTimer()
}
